package com.superiorslayertracker;

import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Coalesces {@link ConfigManager#sendConfig()} onto a background thread so
 * combat / task-assignment paths are not blocked by a full profile flush.
 */
@Slf4j
@Singleton
public class DebouncedConfigFlush
{
	private static final long FLUSH_DELAY_MS = 1500L;

	@Inject
	private ConfigManager configManager;

	private final Object lock = new Object();
	private boolean dirty;
	private ScheduledExecutorService flushExecutor;
	private ScheduledFuture<?> pendingFlush;

	public void start()
	{
		synchronized (lock)
		{
			if (flushExecutor != null)
			{
				return;
			}
			flushExecutor = Executors.newSingleThreadScheduledExecutor(r ->
			{
				final Thread t = new Thread(r, "superior-slayer-tracker-config-flush");
				t.setDaemon(true);
				return t;
			});
		}
	}

	/** Flush pending writes and stop the scheduler. */
	public void shutdown()
	{
		flushNow();
		synchronized (lock)
		{
			if (flushExecutor != null)
			{
				flushExecutor.shutdownNow();
				flushExecutor = null;
			}
			pendingFlush = null;
		}
	}

	/** Mark config dirty and schedule a debounced disk/cloud flush. */
	public void scheduleFlush()
	{
		synchronized (lock)
		{
			dirty = true;
			if (flushExecutor == null)
			{
				return;
			}
			if (pendingFlush != null)
			{
				pendingFlush.cancel(false);
			}
			pendingFlush = flushExecutor.schedule(this::flushNow, FLUSH_DELAY_MS, TimeUnit.MILLISECONDS);
		}
	}

	/** Cancel any pending debounce and flush immediately if dirty. */
	public void flushNow()
	{
		final boolean shouldFlush;
		synchronized (lock)
		{
			if (pendingFlush != null)
			{
				pendingFlush.cancel(false);
				pendingFlush = null;
			}
			shouldFlush = dirty;
			dirty = false;
		}

		if (shouldFlush)
		{
			configManager.sendConfig();
		}
	}
}

package com.superiorslayertracker;

/**
 * Expected imbued-heart contribution from superior kills, including Mortimer
 * superior-unique modifiers.
 * <p>
 * {@code +X% Superior unique chance} increases the base chance by X%, i.e.
 * multiplier {@code 1 + X/100}. A Night Beast task at {@code +300%} goes from
 * {@code 1/256} to {@code 4/256} = {@code 1/64}.
 */
public final class HeartExpectation
{
	private HeartExpectation()
	{
	}

	/**
	 * Multiplier applied to the base heart rate ({@code 1/N → multiplier/N}).
	 * {@code null} or {@code <= 0} means no bonus (1.0×).
	 * A logged {@code 80} means +80%, i.e. 1.8×.
	 */
	public static double uniqueTableMultiplier(Integer superiorDropRateModifierPercent)
	{
		if (superiorDropRateModifierPercent == null || superiorDropRateModifierPercent <= 0)
		{
			return 1.0d;
		}
		return 1.0d + superiorDropRateModifierPercent / 100.0d;
	}

	/**
	 * Expected hearts from one kill of {@code monster} with an optional Mortimer modifier.
	 */
	public static double expectedHeartsFromKill(SuperiorMonster monster, Integer superiorDropRateModifierPercent)
	{
		if (monster == null)
		{
			return 0.0d;
		}
		final int rate = monster.getHeartRarityDenominator();
		if (rate <= 0)
		{
			return 0.0d;
		}
		return uniqueTableMultiplier(superiorDropRateModifierPercent) / rate;
	}

	/**
	 * Effective kill weight toward the base 1/rate dry bar (1.0 per unmodified kill).
	 */
	public static double effectiveKillWeight(Integer superiorDropRateModifierPercent)
	{
		return uniqueTableMultiplier(superiorDropRateModifierPercent);
	}

	/**
	 * Effective heart denominator after applying the modifier ({@code N / multiplier}).
	 */
	public static double effectiveHeartDenominator(SuperiorMonster monster, Integer superiorDropRateModifierPercent)
	{
		if (monster == null)
		{
			return Double.POSITIVE_INFINITY;
		}
		final int rate = monster.getHeartRarityDenominator();
		final double multiplier = uniqueTableMultiplier(superiorDropRateModifierPercent);
		if (rate <= 0 || multiplier <= 0d)
		{
			return Double.POSITIVE_INFINITY;
		}
		return rate / multiplier;
	}
}

package com.superiorslayertracker;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Pure helpers for one-shot Loot Tracker → superior kill log import.
 */
final class LootTrackerImportLogic
{
	static final String ID_PREFIX = "loottracker:";

	private LootTrackerImportLogic()
	{
	}

	static String stableId(String rsProfileKey, String monsterDisplayName, int index)
	{
		return ID_PREFIX + rsProfileKey + ":" + normalize(monsterDisplayName) + ":" + index;
	}

	static boolean isImportStubId(String uniqueId)
	{
		return uniqueId != null && uniqueId.startsWith(ID_PREFIX);
	}

	static int countMonsterKills(List<SuperiorKill> kills, SuperiorMonster monster)
	{
		int count = 0;
		for (SuperiorKill kill : kills)
		{
			if (monster.equals(SuperiorMonster.fromNpcName(kill.getMonsterName())))
			{
				count++;
			}
		}
		return count;
	}

	static int countImportStubs(List<SuperiorKill> kills, SuperiorMonster monster)
	{
		int count = 0;
		for (SuperiorKill kill : kills)
		{
			if (!isImportStubId(kill.getUniqueID()))
			{
				continue;
			}
			if (monster.equals(SuperiorMonster.fromNpcName(kill.getMonsterName())))
			{
				count++;
			}
		}
		return count;
	}

	static int killsToImport(int lootTrackerKills, int existingLogKills)
	{
		return Math.max(0, lootTrackerKills - existingLogKills);
	}

	static List<SuperiorKill> buildStubs(
		String rsProfileKey,
		long accountHash,
		SuperiorMonster monster,
		int toAdd,
		int existingImportStubCount,
		long timestampMs
	)
	{
		final List<SuperiorKill> stubs = new ArrayList<>(toAdd);
		for (int i = 0; i < toAdd; i++)
		{
			final int index = existingImportStubCount + i;
			final SuperiorKill kill = new SuperiorKill();
			kill.setUniqueID(stableId(rsProfileKey, monster.getDisplayName(), index));
			kill.setTimestamp(timestampMs);
			kill.setAccountHash(accountHash);
			kill.setMonsterName(monster.getDisplayName());
			kill.setNpcId(0);
			kill.setLoot(new ArrayList<>());
			kill.setImbuedHeart(false);
			kill.setEternalGem(false);
			kill.setMistBattlestaff(false);
			kill.setDustBattlestaff(false);
			kill.setSuperiorDropRateModifier(null);
			stubs.add(kill);
		}
		return stubs;
	}

	static Set<String> existingIds(List<SuperiorKill> kills)
	{
		final Set<String> ids = new HashSet<>();
		for (SuperiorKill kill : kills)
		{
			if (kill.getUniqueID() != null)
			{
				ids.add(kill.getUniqueID());
			}
		}
		return ids;
	}

	private static String normalize(String name)
	{
		return name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "");
	}
}

package com.superiorslayertracker;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;

/**
 * One-shot import of aggregated superior kill counts from RuneLite Loot Tracker.
 */
@Slf4j
@Singleton
public class LootTrackerImportService
{
	static final String LOOT_TRACKER_GROUP = "loottracker";
	static final String KEY_IMPORT_DONE = "lootTrackerImportDone";
	private static final String DROPS_NPC_PREFIX = "drops_NPC_";

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SuperiorKillStorage killStorage;

	@Inject
	private Gson gson;

	public boolean isImportDone()
	{
		final Boolean done = configManager.getRSProfileConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_IMPORT_DONE, Boolean.class);
		return Boolean.TRUE.equals(done);
	}

	public void resetImportState()
	{
		configManager.unsetRSProfileConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_IMPORT_DONE);
		log.info("Loot Tracker import flag cleared");
	}

	private void markImportDone()
	{
		configManager.setRSProfileConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_IMPORT_DONE, true);
	}

	/**
	 * Imports missing superior kill stubs from Loot Tracker aggregates.
	 *
	 * @return number of stub kills written, or -1 if blocked / unavailable
	 */
	public int importFromLootTracker()
	{
		if (isImportDone())
		{
			log.info("Loot Tracker import already completed; skipping");
			return -1;
		}

		final String rsProfileKey = configManager.getRSProfileKey();
		if (rsProfileKey == null || rsProfileKey.isEmpty())
		{
			log.warn("Cannot import from Loot Tracker: no RS profile");
			return -1;
		}

		final ArrayList<SuperiorKill> existing = killStorage.loadKills();
		final Set<String> existingIds = LootTrackerImportLogic.existingIds(existing);
		final long accountHash = client.getAccountHash();

		int written = 0;
		int readableAggregates = 0;
		for (SuperiorMonster monster : SuperiorMonster.values())
		{
			final LootTrackerNpcAggregate aggregate = readAggregate(monster.getDisplayName());
			if (aggregate == null)
			{
				continue;
			}
			readableAggregates++;
			if (aggregate.getKills() <= 0)
			{
				continue;
			}

			final int existingKills = LootTrackerImportLogic.countMonsterKills(existing, monster);
			final int toAdd = LootTrackerImportLogic.killsToImport(aggregate.getKills(), existingKills);
			if (toAdd <= 0)
			{
				continue;
			}

			final int existingStubs = LootTrackerImportLogic.countImportStubs(existing, monster);
			final long timestamp = aggregate.getLast() > 0
				? aggregate.getLast()
				: (aggregate.getFirst() > 0 ? aggregate.getFirst() : 0L);

			final List<SuperiorKill> stubs = LootTrackerImportLogic.buildStubs(
				rsProfileKey,
				accountHash,
				monster,
				toAdd,
				existingStubs,
				timestamp
			);

			for (SuperiorKill stub : stubs)
			{
				if (existingIds.contains(stub.getUniqueID()))
				{
					continue;
				}
				existing.add(stub);
				existingIds.add(stub.getUniqueID());
				written++;
			}

			log.info(
				"Loot Tracker import: {} — LT kills={}, log kills={}, added={}",
				monster.getDisplayName(),
				aggregate.getKills(),
				existingKills,
				toAdd
			);
		}

		if (readableAggregates == 0)
		{
			log.warn("Loot Tracker import found no readable superior aggregates; not marking done");
			return -1;
		}

		if (written > 0)
		{
			killStorage.saveKills(existing);
		}

		markImportDone();
		log.info("Loot Tracker import finished; wrote {} stub kills", written);
		return written;
	}

	private LootTrackerNpcAggregate readAggregate(String npcName)
	{
		final String key = DROPS_NPC_PREFIX + npcName;
		// ConfigManager only auto-unmarshals a fixed set of types; everything else
		// is returned as the raw JSON string (RuneLite 1.12+).
		final String json = configManager.getRSProfileConfiguration(LOOT_TRACKER_GROUP, key);
		if (json == null || json.isEmpty())
		{
			return null;
		}

		try
		{
			return gson.fromJson(json, LootTrackerNpcAggregate.class);
		}
		catch (JsonSyntaxException e)
		{
			log.debug("Failed parsing Loot Tracker aggregate for {}: {}", npcName, e.getMessage());
			return null;
		}
	}
}

package com.superiorslayertracker;

import lombok.Data;

/**
 * Minimal mirror of Loot Tracker's persisted NPC aggregate JSON.
 * {@code first}/{@code last} are epoch millis.
 */
@Data
class LootTrackerNpcAggregate
{
	private String type;
	private String name;
	private int kills;
	private long first;
	private long last;
}

package com.superiorslayertracker;

import lombok.Data;

import java.util.ArrayList;
import java.util.List;

@Data
public class SuperiorKill
{
	private String uniqueID;
	private long timestamp;
	private long accountHash;
	private String monsterName;
	private int npcId;
	private List<SuperiorLootItem> loot = new ArrayList<>();
	private boolean imbuedHeart;
