	 */
	private Integer superiorDropRateModifier;
}

package com.superiorslayertracker;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Persists superior kill data per RS account via ConfigManager, so it follows
 * RuneLite profiles and cloud sync.
 * <p>
 * Keeps an in-memory cache and debounces disk flushes via
 * {@link DebouncedConfigFlush} so superior kills do not block the client thread.
 */
@Slf4j
@Singleton
public class SuperiorKillStorage
{
	static final String KEY_KILLS = "kills";

	private static final Type KILL_LIST_TYPE = new TypeToken<ArrayList<SuperiorKill>>()
	{
	}.getType();

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private DebouncedConfigFlush configFlush;

	private final Object lock = new Object();

	private ArrayList<SuperiorKill> cachedKills;
	private String cachedProfileKey;

	/** True once an RS profile is available (i.e. the player is logged in). */
	public boolean isReady()
	{
		final String profileKey = configManager.getRSProfileKey();
		return profileKey != null && !profileKey.isEmpty();
	}

	/**
	 * Returns a defensive copy of the cached kill list, loading from config
	 * on first use or when the RS profile changes.
	 */
	public ArrayList<SuperiorKill> loadKills()
	{
		synchronized (lock)
		{
			ensureCacheLoaded();
			return new ArrayList<>(cachedKills);
		}
	}

	/**
	 * Replaces the kill list (e.g. Loot Tracker import) and flushes immediately.
	 */
	public void saveKills(List<SuperiorKill> kills)
	{
		synchronized (lock)
		{
			ensureCacheLoaded();
			cachedKills = new ArrayList<>(kills);
			writeConfigMemory();
		}
		configFlush.scheduleFlush();
		configFlush.flushNow();
	}

	/**
	 * Appends a kill in memory, updates ConfigManager, and schedules a
	 * debounced disk/cloud flush (safe to call from the client thread).
	 */
	public void addKill(SuperiorKill kill)
	{
		synchronized (lock)
		{
			ensureCacheLoaded();
			cachedKills.add(kill);
			writeConfigMemory();
			configFlush.scheduleFlush();
		}
	}

	public void clearKills()
	{
		synchronized (lock)
		{
			final String profileKey = configManager.getRSProfileKey();
			cachedKills = new ArrayList<>();
			cachedProfileKey = profileKey;
			configManager.unsetRSProfileConfiguration(
				SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_KILLS);
		}
		configFlush.scheduleFlush();
		configFlush.flushNow();
	}

	private void ensureCacheLoaded()
	{
		final String profileKey = configManager.getRSProfileKey();
		if (profileKey == null || profileKey.isEmpty())
		{
			cachedKills = new ArrayList<>();
			cachedProfileKey = null;
			return;
		}

		if (cachedKills != null && profileKey.equals(cachedProfileKey))
		{
			return;
		}

		cachedProfileKey = profileKey;
		cachedKills = readFromConfig();
	}

	private ArrayList<SuperiorKill> readFromConfig()
	{
		final String json = configManager.getRSProfileConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_KILLS);
		if (json == null || json.isEmpty())
		{
			return new ArrayList<>();
		}

		try
		{
			final ArrayList<SuperiorKill> kills = gson.fromJson(json, KILL_LIST_TYPE);
			return kills != null ? kills : new ArrayList<>();
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Failed to parse stored superior kills", e);
			return new ArrayList<>();
		}
	}

	private void writeConfigMemory()
	{
		configManager.setRSProfileConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP,
			KEY_KILLS,
			gson.toJson(cachedKills, KILL_LIST_TYPE));
	}
}

