package com.superiorslayertracker;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Superior slayer monsters that can drop the imbued heart and eternal gem.
 * Drop rates from https://oldschool.runescape.wiki/w/Imbued_heart
 * <p>
 * Formula: 1 / (8 * (200 - floor((slayerReq + 55)^2 / 125)))
 * The eternal gem shares the same drop rate as the imbued heart.
 */
public enum SuperiorMonster
{
	GREATER_ABYSSAL_DEMON("Greater abyssal demon", 342, 352, "greater_abyssal_demon.png"),
	CHOKE_DEVIL("Choke devil", 264, 680, "choke_devil.png"),
	ABHORRENT_SPECTRE("Abhorrent spectre", 253, 760, "abhorrent_spectre.png"),
	NIGHT_BEAST("Night beast", 374, 256, "night_beast.png"),
	KING_KURASK("King kurask", 295, 600, "king_kurask.png"),
	SCREAMING_BANSHEE("Screaming banshee", 70, 1288, "screaming_banshee.png"),
	FLAMING_PYRELORD("Flaming pyrelord", 97, 1144, "flaming_pyrelord.png"),
	CHASM_CRAWLER("Chasm Crawler", 68, 1336, "chasm_crawler.png"),
	GIANT_ROCKSLUG("Giant rockslug", 86, 1240, "giant_rockslug.png"),
	MALEVOLENT_MAGE("Malevolent Mage", 162, 960, "malevolent_mage.png"),
	MARBLE_GARGOYLE("Marble gargoyle", 349, 520, "marble_gargoyle.png"),
	NECHRYARCH("Nechryarch", 300, 440, "nechryarch.png"),
	VITREOUS_JELLY("Vitreous Jelly", 206, 872, "vitreous_jelly.png"),
	CAVE_ABOMINATION("Cave abomination", 206, 784, "cave_abomination.png"),
	REPUGNANT_SPECTRE("Repugnant spectre", 335, 760, "repugnant_spectre.png"),
	INSATIABLE_MUTATED_BLOODVELD("Insatiable mutated Bloodveld", 278, 896, "insatiable_mutated_bloodveld.png"),
	INSATIABLE_BLOODVELD("Insatiable Bloodveld", 202, 896, "insatiable_bloodveld.png"),
	NUCLEAR_SMOKE_DEVIL("Nuclear smoke devil", 280, 200, "nuclear_smoke_devil.png"),
	CRUSHING_HAND("Crushing hand", 45, 1376, "crushing_hand.png"),
	MONSTROUS_BASILISK("Monstrous basilisk", 135, 1024, "monstrous_basilisk.png"),
	COCKATHRICE("Cockathrice", 89, 1192, "cockathrice.png"),
	VITREOUS_WARPED_JELLY("Vitreous Warped Jelly", 241, 872, "vitreous_warped_jelly.png"),
	SCREAMING_TWISTED_BANSHEE("Screaming twisted banshee", 144, 1288, "screaming_twisted_banshee.png"),
	BASILISK_SENTINEL("Basilisk Sentinel", 358, 760, "basilisk_sentinel.png"),
	INFERNAL_PYRELORD("Infernal pyrelord", 134, 1144, "infernal_pyrelord.png"),
	SHADOW_WYRM("Shadow Wyrm", 259, 728, "shadow_wyrm.png"),
	SPIKED_TUROTH("Spiked Turoth", 244, 832, "spiked_turoth.png"),
	GUARDIAN_DRAKE("Guardian Drake", 376, 368, "guardian_drake.png"),
	COLOSSAL_HYDRA("Colossal Hydra", 309, 160, "colossal_hydra.png"),
	MUTATED_TERRORBIRD("Mutated Terrorbird", 178, 816, "mutated_terrorbird.png"),
	MUTATED_TORTOISE("Mutated Tortoise", 247, 816, "mutated_tortoise.png"),
	DREADBORN_ARAXYTE("Dreadborn Araxyte", 281, 224, "dreadborn_araxyte.png"),
	ANCIENT_CUSTODIAN("Ancient Custodian", 239, 504, "ancient_custodian.png"),
	ELDER_AQUANITE("Elder aquanite", 305, 472, "elder_aquanite.png"),
	MAGMA_STRYKEWYRM("Magma strykewyrm", 249, 728, "magma_strykewyrm.png"),
	DIRE_GRYPHON("Dire gryphon", 209, 888, "dire_gryphon.png"),
	VITREOUS_CHILLED_JELLY("Vitreous Chilled Jelly", 241, 872, "vitreous_chilled_jelly.png"),
	BLOOD_STARVED_VENATOR("Blood-starved venator", 246, 536, "blood_starved_venator.png");

	private static final Map<String, SuperiorMonster> BY_NAME = new HashMap<>();

	static
	{
		for (SuperiorMonster monster : values())
		{
			BY_NAME.put(monster.displayName.toLowerCase(Locale.ROOT), monster);
		}
	}

	private final String displayName;
	private final int combatLevel;
	private final int heartRarityDenominator;
	private final String iconFileName;

	SuperiorMonster(String displayName, int combatLevel, int heartRarityDenominator, String iconFileName)
	{
		this.displayName = displayName;
		this.combatLevel = combatLevel;
		this.heartRarityDenominator = heartRarityDenominator;
		this.iconFileName = iconFileName;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getCombatLevel()
	{
		return combatLevel;
	}

	public int getHeartRarityDenominator()
	{
		return heartRarityDenominator;
	}

	public String getIconFileName()
	{
		return iconFileName;
	}

	public String getIconResourcePath()
	{
		return "icons/" + iconFileName;
	}

	public static SuperiorMonster fromNpcName(String npcName)
	{
		if (npcName == null || npcName.isEmpty())
		{
			return null;
		}

		return BY_NAME.get(npcName.toLowerCase(Locale.ROOT));
	}
}

package com.superiorslayertracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SuperiorSlayerTrackerConfig.CONFIG_GROUP)
public interface SuperiorSlayerTrackerConfig extends Config
{
	String CONFIG_GROUP = "superiorslayertracker";

	@ConfigItem(
		keyName = "showTitle",
		name = "Show Title",
		description = "Disable to hide the title in the side panel"
	)
	default boolean showTitle()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOnlyKilled",
		name = "Show Only Killed",
		description = "When enabled, only superiors with at least one kill are shown"
	)
	default boolean showOnlyKilled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "taskCompletionSummary",
		name = "Task Completion Message",
		description = "Show superiors killed vs expected in the chat box when a slayer task is completed"
	)
	default boolean taskCompletionSummary()
	{
		return false;
	}

	@ConfigItem(
		keyName = "eliteCombatAchievements",
		name = "Elite Combat Achievements",
		description = "Enable if the Elite Combat Achievements tier is complete - superiors spawn at a rate of 1/150 instead of 1/200"
	)
	default boolean eliteCombatAchievements()
	{
		return false;
	}
}

package com.superiorslayertracker;

import com.google.inject.Provides;
import com.superiorslayertracker.ui.SuperiorSlayerTrackerPanel;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collection;
import java.util.UUID;

@Slf4j
@PluginDescriptor(
	name = "Superior Slayer Tracker"
)
public class SuperiorSlayerTrackerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SuperiorSlayerTrackerConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SuperiorKillStorage killStorage;

	@Inject
	private DebouncedConfigFlush configFlush;

	@Inject
	private EventBus eventBus;

	@Inject
	private TaskModifierTracker taskModifierTracker;

	@Inject
	private TaskKillTracker taskKillTracker;

	@Inject
	private LootTrackerImportService lootTrackerImportService;

	private SuperiorSlayerTrackerPanel panel;
	private NavigationButton navButton;

	@Provides
	SuperiorSlayerTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SuperiorSlayerTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		configFlush.start();
		panel = new SuperiorSlayerTrackerPanel(killStorage, config, client, lootTrackerImportService);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel-icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Superior Slayer Tracker")
			.priority(6)
			.icon(icon)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		eventBus.register(taskModifierTracker);
		taskModifierTracker.loadPersistedState();
		eventBus.register(taskKillTracker);
		taskKillTracker.loadPersistedState();
		refreshKillList();
	}

	@Override
	protected void shutDown()
	{
		configFlush.shutdown();
		eventBus.unregister(taskModifierTracker);
		eventBus.unregister(taskKillTracker);
		clientToolbar.removeNavigation(navButton);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!SuperiorSlayerTrackerConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		SwingUtilities.invokeLater(panel::updateView);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGING_IN || event.getGameState() == GameState.LOGGED_IN)
		{
			refreshKillList();
		}
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		final NPC npc = event.getNpc();
		if (npc == null || npc.getName() == null)
		{
			return;
		}

		final SuperiorMonster monster = SuperiorMonster.fromNpcName(npc.getName());
		if (monster == null)
		{
			return;
		}

		taskKillTracker.recordSuperiorKill();

		if (!killStorage.isReady())
		{
			log.warn("Cannot log superior kill; RS profile not ready");
			return;
		}

		final SuperiorKill kill = buildKill(monster, npc.getId(), event.getItems());
		killStorage.addKill(kill);

		SwingUtilities.invokeLater(() -> panel.addKill(kill));
		log.info(
			"Logged superior kill: {} (npcId={}, superiorUniqueBonus={})",
			monster.getDisplayName(),
			npc.getId(),
			kill.getSuperiorDropRateModifier());
	}

	private SuperiorKill buildKill(SuperiorMonster monster, int npcId, Collection<ItemStack> items)
	{
		final SuperiorKill kill = new SuperiorKill();
		kill.setUniqueID(UUID.randomUUID().toString());
		kill.setTimestamp(System.currentTimeMillis());
		kill.setAccountHash(client.getAccountHash());
		kill.setMonsterName(monster.getDisplayName());
		kill.setNpcId(npcId);
		kill.setSuperiorDropRateModifier(taskModifierTracker.getActiveSuperiorUniqueBonus());

		final ArrayList<SuperiorLootItem> loot = new ArrayList<>();
		boolean imbuedHeart = false;
		boolean eternalGem = false;
		boolean mistBattlestaff = false;
		boolean dustBattlestaff = false;

		for (ItemStack stack : items)
		{
			final int itemId = stack.getId();
			final ItemComposition composition = itemManager.getItemComposition(itemId);
			final SuperiorLootItem lootItem = new SuperiorLootItem();
			lootItem.setId(itemId);
			lootItem.setName(composition.getName());
			lootItem.setQuantity(stack.getQuantity());
			lootItem.setPrice(itemManager.getItemPrice(itemId));
			loot.add(lootItem);

			if (itemId == ItemID.IMBUED_HEART)
			{
				imbuedHeart = true;
			}
			else if (itemId == ItemID.SLAYER_ETERNAL_GEM)
			{
				eternalGem = true;
			}
			else if (itemId == ItemID.MIST_BATTLESTAFF)
			{
				mistBattlestaff = true;
			}
			else if (itemId == ItemID.DUST_BATTLESTAFF)
			{
				dustBattlestaff = true;
			}
		}

		kill.setLoot(loot);
		kill.setImbuedHeart(imbuedHeart);
		kill.setEternalGem(eternalGem);
		kill.setMistBattlestaff(mistBattlestaff);
		kill.setDustBattlestaff(dustBattlestaff);
		return kill;
	}

	private void refreshKillList()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGIN_SCREEN)
			{
				return;
			}

			panel.loadKillList();
		});
	}
}

package com.superiorslayertracker;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Counts superiors killed during the current slayer task and prints an optional
 * "superiors killed vs expected" recap when the task completes.
 *
 * <p>Expected superiors uses the kill count from the game's completion message
 * ("You have completed your task! You killed N ..."), which is the actual number
 * of monsters killed and already reflects bracelet of slaughter / expeditious
 * bracelet effects. Superior kills are tracked separately via loot events.
 */
@Slf4j
@Singleton
public class TaskKillTracker
{
	private static final String KEY_TASK_KILLS = "taskKillCount";
	private static final String KEY_TASK_SUPERIORS = "taskSuperiorKillCount";

	// Same live-message prefixes RuneLite's slayer plugin matches on.
	private static final String CHAT_BRACELET_SLAUGHTER = "Your bracelet of slaughter prevents your slayer";
	private static final String CHAT_BRACELET_EXPEDITIOUS = "Your expeditious bracelet helps you progress your";
	private static final String CHAT_CANCEL_MESSAGE = "Your task has been cancelled.";

	static final Pattern TASK_COMPLETE_MESSAGE = Pattern.compile(
		"^You have completed your task! You killed ([\\d,]+) (.+?)\\.");

	private static final double SUPERIOR_RATE_BASE = 200.0;
	private static final double SUPERIOR_RATE_ELITE_CA = 150.0;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private DebouncedConfigFlush configFlush;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private SuperiorSlayerTrackerConfig config;

	private int taskKills;
	private int taskSuperiors;
	private int lastCount = -1;
	private int lastTarget = -1;

	/**
	 * False after login/hop until {@link #reconcileAfterLogin(int)} adopts the
	 * live varps. While false, varp updates only refresh baselines so hydration
	 * (count streaming 0 -> N) is never mistaken for a new task.
	 */
	private boolean slayerVarpsHydrated;

	void loadPersistedState()
	{
		final Integer kills = configManager.getConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TASK_KILLS, Integer.class);
		final Integer superiors = configManager.getConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TASK_SUPERIORS, Integer.class);

		taskKills = kills != null ? kills : 0;
		taskSuperiors = superiors != null ? superiors : 0;

		if (taskKills > 0 || taskSuperiors > 0)
		{
			log.info("Restored task counters: {} kills, {} superiors", taskKills, taskSuperiors);
		}

		// Plugin reload while already in-game never gets a fresh LOGGED_IN event.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() -> reconcileAfterLogin(0));
		}
	}

	/** Called when a superior slayer creature kill is logged. */
	void recordSuperiorKill()
	{
		taskSuperiors++;
		persist();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			lastCount = -1;
			lastTarget = -1;
			slayerVarpsHydrated = false;
			return;
		}

		if (state == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() -> reconcileAfterLogin(0));
		}
	}

	/**
	 * After login/hop, adopt the current slayer varps as baselines without
	 * counting the jump from 0 as kills or a task change.
	 */
	private void reconcileAfterLogin(int attempt)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);

		// Slayer varps stream in over the first ticks after login; wait for them
		// before adopting baselines (mirrors TaskModifierTracker).
		if (count == 0 && target == 0 && attempt < 10)
		{
			final int next = attempt + 1;
			clientThread.invokeLater(() -> reconcileAfterLogin(next));
			return;
		}

		lastCount = count;
		lastTarget = target;
		slayerVarpsHydrated = true;
		log.debug("Task kill tracker hydrated (count={} target={} kills={} superiors={})",
			count, target, taskKills, taskSuperiors);
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		final int varpId = event.getVarpId();
		if (varpId != VarPlayerID.SLAYER_COUNT && varpId != VarPlayerID.SLAYER_TARGET)
		{
			return;
		}

		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);

		if (!slayerVarpsHydrated)
		{
			lastCount = count;
			lastTarget = target;
			return;
		}

		final boolean targetChanged = target != lastTarget && target > 0;
		final boolean countIncreased = count > lastCount;
		final boolean taskStarted = count > 0
			&& (lastCount <= 0 || targetChanged || countIncreased);

		final int previousCount = lastCount;
		lastCount = count;
		lastTarget = target;

		if (taskStarted)
		{
			resetCounters("new slayer task");
			return;
		}

		if (previousCount > 0 && count < previousCount)
		{
			taskKills += previousCount - count;
			persist();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		final String msg = Text.removeTags(event.getMessage());
		if (msg == null || msg.isEmpty())
		{
			return;
		}

		if (msg.startsWith(CHAT_BRACELET_SLAUGHTER))
		{
			// Monster died but the slayer count did not decrease.
			taskKills++;
			persist();
			return;
		}

		if (msg.startsWith(CHAT_BRACELET_EXPEDITIOUS))
		{
			// One kill decremented the count by two.
			taskKills = Math.max(0, taskKills - 1);
			persist();
			return;
		}

		if (msg.startsWith(CHAT_CANCEL_MESSAGE))
		{
			resetCounters("task cancelled");
			return;
		}

		final Matcher complete = TASK_COMPLETE_MESSAGE.matcher(msg);
		if (complete.find())
		{
			final int reportedKills = Integer.parseInt(complete.group(1).replace(",", ""));
			onTaskCompleted(reportedKills, complete.group(2).trim());
		}
	}

	private void onTaskCompleted(int reportedKills, String monsterName)
	{
		// The completion message reports actual monsters killed (not the original
		// assignment size). That already accounts for both bracelets: slaughter
		// raises the total, expeditious lowers it. Prefer that figure over our
		// tracked count — Math.max used to pick the assignment-sized total when
		// expeditious was worn and overstate expected superiors.
		final int kills = reportedKills > 0 ? reportedKills : taskKills;
		final int superiors = taskSuperiors;

		log.info("Task complete: {} superiors, {} kills (tracked={})",
			superiors, kills, taskKills);

		if (config.taskCompletionSummary())
		{
			sendSummary(superiors, kills, monsterName);
		}

		// New-task detection resets too; this just keeps post-task kills out.
		resetCounters("task completed");
	}

	private void sendSummary(int superiors, int kills, String monsterName)
	{
		final double rate = config.eliteCombatAchievements()
			? SUPERIOR_RATE_ELITE_CA
			: SUPERIOR_RATE_BASE;
		final double expected = kills / rate;

		final String message = new ChatMessageBuilder()
			.append(ChatColorType.NORMAL)
			.append("Superiors: ")
			.append(ChatColorType.HIGHLIGHT)
			.append(Integer.toString(superiors))
			.append(ChatColorType.NORMAL)
			.append(" killed / ")
			.append(ChatColorType.HIGHLIGHT)
			.append(String.format(Locale.ROOT, "%.2f", expected))
			.append(ChatColorType.NORMAL)
			.append(" expected (")
			.append(ChatColorType.HIGHLIGHT)
			.append(Integer.toString(kills))
			.append(ChatColorType.NORMAL)
			.append(" " + monsterName + " killed).")
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	private void resetCounters(String reason)
	{
		if (taskKills == 0 && taskSuperiors == 0)
		{
			return;
		}

		log.info("Resetting task counters ({}): {} kills, {} superiors dropped",
			reason, taskKills, taskSuperiors);
		taskKills = 0;
		taskSuperiors = 0;
		persist();
	}

	private void persist()
	{
		configManager.setConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TASK_KILLS, taskKills);
		configManager.setConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TASK_SUPERIORS, taskSuperiors);
		configFlush.scheduleFlush();
	}
}

package com.superiorslayertracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure parsing helpers for Mortimer task-choice / assignment modifier text.
 */
final class TaskModifierParser
{
	static final Pattern SUPERIOR_UNIQUE_BONUS = Pattern.compile(
		"(?i)\\+?(\\d+)\\s*%\\s*Superior unique chance");

	private static final Pattern NEW_TASK = Pattern.compile(
		"(?i)Your new task is to kill\\s+(\\d+)\\s+(.+?)(?:\\.|(?=Completing)|$)");

	private TaskModifierParser()
	{
	}

	static Integer parseSuperiorUniqueBonus(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}

		final Matcher matcher = SUPERIOR_UNIQUE_BONUS.matcher(text);
		if (!matcher.find())
		{
			return null;
		}

		return Integer.parseInt(matcher.group(1));
	}

	static String parseAssignedTaskName(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}

		final Matcher matcher = NEW_TASK.matcher(text.replace('\n', ' '));
		if (!matcher.find())
		{
			return null;
		}

		return matcher.group(2).trim();
	}

	/**
	 * Walk ordered widget texts from the Slayer Task Choice UI and map creature
	 * names to superior-unique bonuses when present on that offer.
	 */
	static Map<String, Integer> parseChoiceOffers(List<String> texts)
	{
		if (texts == null || texts.isEmpty())
		{
			return Collections.emptyMap();
		}

		final Map<String, Integer> offers = new LinkedHashMap<>();
		String lastCreature = null;

		for (String raw : texts)
		{
			if (raw == null)
			{
				continue;
			}

			final String text = raw.trim();
			if (text.isEmpty())
			{
				continue;
			}

			final Integer bonus = parseSuperiorUniqueBonus(text);
			if (bonus != null)
			{
				if (lastCreature != null)
				{
					offers.put(normalizeTaskKey(lastCreature), bonus);
				}
				continue;
			}

			if (isIgnorableChoiceText(text))
			{
				continue;
			}

			if (looksLikeCreatureName(text))
			{
				lastCreature = text;
			}
		}

		return offers;
	}

	static Integer lookupOffer(Map<String, Integer> offers, String taskName)
	{
		if (offers == null || offers.isEmpty() || taskName == null || taskName.isEmpty())
		{
			return null;
		}

		final String key = normalizeTaskKey(taskName);
		final Integer exact = offers.get(key);
		if (exact != null)
		{
			return exact;
		}

		for (Map.Entry<String, Integer> entry : offers.entrySet())
		{
			if (key.contains(entry.getKey()) || entry.getKey().contains(key))
			{
				return entry.getValue();
			}
		}

		return null;
	}

	static String normalizeTaskKey(String name)
	{
		return name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "");
	}

	private static boolean isIgnorableChoiceText(String text)
	{
		final String lower = text.toLowerCase(Locale.ROOT);
		return lower.equals("slayer task choice")
			|| lower.startsWith("amount")
			|| lower.startsWith("complete ")
			|| lower.contains("unlock a third choice")
			|| lower.matches("\\d+\\s+to\\s+\\d+")
			|| lower.matches("\\+\\d+.*")
			|| lower.contains("clue chance")
			|| lower.contains("slayer points")
			|| lower.contains("slayer xp")
			|| lower.contains("task quantity");
	}

	private static boolean looksLikeCreatureName(String text)
	{
		if (text.length() < 3 || text.length() > 40)
		{
			return false;
		}
		if (!Character.isLetter(text.charAt(0)))
		{
			return false;
		}
		// Reject pure modifier / amount fragments already handled above.
		return !text.contains("%") && !text.contains("+");
	}

	static List<String> copyNonBlank(List<String> texts)
	{
		if (texts == null || texts.isEmpty())
		{
			return Collections.emptyList();
		}
		final List<String> copy = new ArrayList<>();
		for (String text : texts)
		{
			if (text != null && !text.trim().isEmpty())
			{
				copy.add(text.trim());
			}
		}
		return copy;
	}
}

package com.superiorslayertracker;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Tracks Mortimer "Superior unique chance" task modifiers from the choice UI
 * and assignment dialog, then exposes the active bonus for superior kill logs.
 */
@Slf4j
@Singleton
public class TaskModifierTracker
{
	/** Mortimer Slayer Task Choice interface (from live probe). */
	static final int SLAYER_TASK_CHOICE_GROUP = 236;

	private static final String KEY_BONUS = "activeSuperiorUniqueBonus";
	private static final String KEY_TARGET = "activeSuperiorUniqueTaskTarget";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private DebouncedConfigFlush configFlush;

	@Getter
	private Integer activeSuperiorUniqueBonus;

	private int activeTaskTarget = -1;
	private int lastCount = -1;
	private int lastTarget = -1;

	/**
	 * False after login/hop until {@link #reconcileAfterLogin()} runs. While false,
	 * slayer varp updates only refresh baselines and must not clear a restored bonus
	 * (target IDs can flicker while the client hydrates).
	 */
	private boolean slayerVarpsHydrated;

	private Map<String, Integer> choiceOffers = Map.of();
	/** True after a choice-UI read until the next task assignment consumes it. */
	private boolean pendingChoiceOffers;

	void loadPersistedState()
	{
		final Integer bonus = configManager.getConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_BONUS, Integer.class);
		final Integer target = configManager.getConfiguration(
			SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TARGET, Integer.class);

		activeSuperiorUniqueBonus = bonus;
		activeTaskTarget = target != null ? target : -1;

		if (activeSuperiorUniqueBonus != null)
		{
			log.info("Restored superior unique bonus +{}% for task target {}",
				activeSuperiorUniqueBonus, activeTaskTarget);
		}

		// Plugin reload while already in-game never gets a fresh LOGGED_IN event.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() -> reconcileAfterLogin(0));
		}
	}

	void clear()
	{
		setActiveBonus(null, -1);
		clearPendingChoiceOffers();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// Keep persisted values; in-memory choice UI cache is session-only.
			clearPendingChoiceOffers();
			lastCount = -1;
			lastTarget = -1;
			slayerVarpsHydrated = false;
			return;
		}

		if (state == GameState.LOGGED_IN)
		{
			// Defer until varps are populated for this login.
			clientThread.invokeLater(() -> reconcileAfterLogin(0));
		}
	}

	/**
	 * After login/hop, adopt current slayer varps and only clear a restored bonus when
	 * the live task target clearly disagrees with what was saved.
	 */
	private void reconcileAfterLogin(int attempt)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);

		// Slayer varps stream in over the first ticks after login; 0/0 with a task on
		// the account usually means they simply haven't arrived yet. Wait before
		// judging, otherwise a restored bonus gets cleared against empty values.
		if (count == 0 && target == 0 && attempt < 10)
		{
			final int next = attempt + 1;
			clientThread.invokeLater(() -> reconcileAfterLogin(next));
			return;
		}

		lastCount = count;
		lastTarget = target;
		slayerVarpsHydrated = true;

		if (activeSuperiorUniqueBonus == null)
		{
			log.debug("Login reconcile: no active superior unique bonus (count={} target={})",
				count, target);
			return;
		}

		if (count > 0 && target > 0 && activeTaskTarget >= 0 && target != activeTaskTarget)
		{
			log.info(
				"Login reconcile: saved bonus target {} != current task target {}; clearing +{}%",
				activeTaskTarget, target, activeSuperiorUniqueBonus);
			setActiveBonus(null, -1);
			return;
		}

		log.info(
			"Login reconcile: keeping superior unique bonus +{}% (task target {}, count={})",
			activeSuperiorUniqueBonus, activeTaskTarget, count);
		persist();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != SLAYER_TASK_CHOICE_GROUP)
		{
			return;
		}

		// Widgets may not be fully populated at the exact load event — refresh next client tick.
		clientThread.invokeLater(this::refreshChoiceOffers);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.DIALOG && event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		final String msg = Text.removeTags(event.getMessage());
		if (msg == null || msg.isEmpty())
		{
			return;
		}

		final Integer dialogBonus = TaskModifierParser.parseSuperiorUniqueBonus(msg);
		final String assignedName = TaskModifierParser.parseAssignedTaskName(msg);

		if (assignedName == null && dialogBonus == null)
		{
			return;
		}

		if (dialogBonus != null)
		{
			final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
			setActiveBonus(dialogBonus, target);
			clearPendingChoiceOffers();
			log.info("Superior unique bonus +{}% from dialog (task={})", dialogBonus, assignedName);
			return;
		}

		// Assignment dialog without an inline superior % — resolve from choice UI cache.
		if (assignedName != null)
		{
			applyOfferForTask(assignedName);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		final int varpId = event.getVarpId();
		if (varpId != VarPlayerID.SLAYER_COUNT && varpId != VarPlayerID.SLAYER_TARGET)
		{
			return;
		}

		final int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);

		// Until login reconcile finishes, only track baselines — never clear restored state.
		if (!slayerVarpsHydrated)
		{
			lastCount = count;
			lastTarget = target;
			return;
		}

		final boolean taskEnded = lastCount > 0 && count == 0;
		// Same-monster reassignment (e.g. cape cancel → same task) bumps count without
		// changing SLAYER_TARGET, so treat a count increase as a new task too.
		final boolean targetChanged = target != lastTarget;
		final boolean countIncreased = count > lastCount;
		final boolean taskStarted = count > 0
			&& (lastCount <= 0 || targetChanged || countIncreased);
		final boolean assignmentSettling = lastCount > 0 && count == lastCount && targetChanged;

		lastCount = count;
		lastTarget = target;

		if (taskEnded)
		{
			// Keep the bonus after count hits 0 so a superior that spawned on the last
			// kill still records the Mortimer modifier when looted.
			log.info("Slayer task cleared; retaining superior unique bonus until next task");
			return;
		}

		if (!taskStarted)
		{
			// Ignore target clearing to 0 (task complete). Only drop the bonus when the
			// game points at a different live task without going through taskStarted.
			if (activeSuperiorUniqueBonus != null && activeTaskTarget >= 0
				&& target > 0 && target != activeTaskTarget)
			{
				log.info(
					"Slayer target changed to {} while bonus bound to {}; clearing +{}%",
					target, activeTaskTarget, activeSuperiorUniqueBonus);
				setActiveBonus(null, -1);
			}
			return;
		}

		// New task with a different monster: drop the previous bonus — unless a sole
		// choice-UI offer is still pending, or COUNT/TARGET are still settling on the
		// same assignment (separate ticks). Premature clear + clearPending caused
		// Banshees +70% to be wiped before the assignment dialog could match.
		final boolean solePendingOffer = pendingChoiceOffers && choiceOffers.size() == 1;
		if (activeSuperiorUniqueBonus != null && activeTaskTarget >= 0 && activeTaskTarget != target
			// target 0 means SLAYER_TARGET hasn't arrived/settled yet (varps stream in
			// one at a time) — never treat that as a different task.
			&& target > 0)
		{
			if (solePendingOffer || assignmentSettling)
			{
				activeTaskTarget = target;
				persist();
			}
			else
			{
				log.info("New slayer task; clearing previous superior unique bonus");
				setActiveBonus(null, -1);
			}
		}

		// Backup while varps settle; leave pendingChoiceOffers for the dialog to confirm.
		if (activeSuperiorUniqueBonus == null && solePendingOffer)
		{
			final Integer only = choiceOffers.values().iterator().next();
			setActiveBonus(only, target);
			log.info("Superior unique bonus +{}% from sole choice-UI offer (pending dialog confirm)", only);
		}
		else if (activeSuperiorUniqueBonus != null && activeTaskTarget < 0)
		{
			activeTaskTarget = target;
			persist();
		}
	}

	private void applyOfferForTask(String taskName)
	{
		final int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);

		if (pendingChoiceOffers)
		{
			final Integer bonus = TaskModifierParser.lookupOffer(choiceOffers, taskName);
			setActiveBonus(bonus, target);
			clearPendingChoiceOffers();
			if (bonus != null)
			{
				log.info("Superior unique bonus +{}% matched choice UI offer for {}", bonus, taskName);
			}
			else
			{
				log.info("Task '{}' has no superior unique choice offer; bonus cleared", taskName);
			}
			return;
		}

		// No choice UI (e.g. slayer cape reassign / back-to-back same task).
		// Keep a retained bonus when the live task target still matches — cape
		// re-rolls of the same monster skip Mortimer's choice screen entirely.
		// If target hasn't hydrated yet (0), keep tentatively; onVarbitChanged
		// will clear if a different monster's target arrives.
		if (activeSuperiorUniqueBonus != null && activeTaskTarget >= 0
			&& (target == 0 || target == activeTaskTarget))
		{
			log.info(
				"Task '{}' reassigned without choice UI; keeping superior unique bonus +{}% (bound target {}, live target {})",
				taskName, activeSuperiorUniqueBonus, activeTaskTarget, target);
			return;
		}

		setActiveBonus(null, target);
		log.info("Task '{}' assigned without choice-UI offers; superior unique bonus cleared", taskName);
	}

	private void refreshChoiceOffers()
	{
		final List<String> texts = new ArrayList<>();
		collectTexts(client.getWidget(SLAYER_TASK_CHOICE_GROUP, 0), texts, 0);
		if (texts.isEmpty())
		{
			return;
		}

		// Keep offers until assignment consumes them — players often sit on the
		// choice screen longer than a short TTL (dialog % is often omitted).
		choiceOffers = TaskModifierParser.parseChoiceOffers(texts);
		pendingChoiceOffers = true;
		if (!choiceOffers.isEmpty())
		{
			log.info("Cached superior unique choice offers: {}", choiceOffers);
		}
		else
		{
			log.debug("Slayer Task Choice opened with no superior unique offers (texts={})", texts.size());
		}
	}

	private void clearPendingChoiceOffers()
	{
		choiceOffers = Map.of();
		pendingChoiceOffers = false;
	}

	private void collectTexts(Widget widget, List<String> out, int depth)
	{
		if (widget == null || depth > 16)
		{
			return;
		}

		final String text = widget.getText();
		if (text != null && !text.isEmpty())
		{
			out.add(Text.removeTags(text));
		}

		collectChildren(widget.getDynamicChildren(), out, depth);
		collectChildren(widget.getStaticChildren(), out, depth);
		collectChildren(widget.getNestedChildren(), out, depth);
	}

	private void collectChildren(Widget[] children, List<String> out, int depth)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			collectTexts(child, out, depth + 1);
		}
	}

	private void setActiveBonus(Integer bonus, int taskTarget)
	{
		activeSuperiorUniqueBonus = bonus;
		activeTaskTarget = bonus == null ? -1 : taskTarget;
		persist();
	}

	private void persist()
	{
		if (activeSuperiorUniqueBonus == null)
		{
			configManager.unsetConfiguration(SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_BONUS);
			configManager.unsetConfiguration(SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TARGET);
		}
		else
		{
			configManager.setConfiguration(
				SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_BONUS, activeSuperiorUniqueBonus);
			configManager.setConfiguration(
				SuperiorSlayerTrackerConfig.CONFIG_GROUP, KEY_TARGET, activeTaskTarget);
		}

		// ConfigManager otherwise only flushes ~every 5 minutes / on clean shutdown.
		// Debounce the disk write so Mortimer task selection does not hitch the client.
		configFlush.scheduleFlush();
	}
}

package com.superiorslayertracker.ui;

import com.superiorslayertracker.HeartExpectation;
