package com.superiorslayertracker;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class TaskModifierParserTest
{
	@Test
	public void parsesSuperiorUniqueBonusFromUiText()
	{
		assertEquals(Integer.valueOf(280),
			TaskModifierParser.parseSuperiorUniqueBonus("+280% Superior unique chance"));
		assertEquals(Integer.valueOf(55),
			TaskModifierParser.parseSuperiorUniqueBonus("55% Superior unique chance"));
		assertNull(TaskModifierParser.parseSuperiorUniqueBonus("+105% Clue chance"));
		assertNull(TaskModifierParser.parseSuperiorUniqueBonus("+10 Slayer points"));
	}

	@Test
	public void parsesAssignedTaskNameFromDialog()
	{
		assertEquals("Crawling Hands", TaskModifierParser.parseAssignedTaskName(
			"Mortimer|Excellent, you're doing great. Your new task is to kill 38 Crawling Hands. "
				+ "Completing this task will award 10 bonus Slayer Points."));
		assertEquals("Basilisks", TaskModifierParser.parseAssignedTaskName(
			"Your new task is to kill 52 Basilisks. Completing this task will grant +280% Superior unique chance."));
	}

	@Test
	public void parsesChoiceOffersFromOrderedWidgetTexts()
	{
		final List<String> texts = Arrays.asList(
			"Slayer Task Choice",
			"Cave Horrors",
			"Amount",
			"80 to 120",
			"+55% Slayer XP",
			"Basilisks",
			"Amount",
			"40 to 60",
			"+280% Superior unique chance",
			"Venators",
			"Amount",
			"120 to 180",
			"+145% Clue chance",
			"Complete 50 tasks with Mortimer to unlock a third choice.");

		final Map<String, Integer> offers = TaskModifierParser.parseChoiceOffers(texts);
		assertEquals(1, offers.size());
		assertEquals(Integer.valueOf(280), offers.get(TaskModifierParser.normalizeTaskKey("Basilisks")));
		assertEquals(Integer.valueOf(280), TaskModifierParser.lookupOffer(offers, "Basilisks"));
		assertNull(TaskModifierParser.lookupOffer(offers, "Cave Horrors"));
	}

	@Test
	public void normalizeTaskKeyStripsNoise()
	{
		assertEquals("crawlinghands", TaskModifierParser.normalizeTaskKey("Crawling Hands"));
		assertTrue(TaskModifierParser.normalizeTaskKey("Blood-starved venators")
			.contains("venator"));
	}
}
